const VOICE_LAYOUT={ko:{settings:'카메라 설정',title:'곁에서 듣고 있어요',flow:'말하면 답하고, 다시 들어요',sound:'소리 켜기',heard:'내가 한 말',live:'음성 동행'},en:{settings:'Camera settings',title:'Right here with you',flow:'Speak. Hear your reply. Keep going.',sound:'Enable sound',heard:'You said',live:'VOICE COMPANION'},zh:{settings:'相机设置',title:'一直在你身边',flow:'你说，我回答，然后继续听',sound:'开启声音',heard:'你刚才说',live:'语音陪伴'}};
import {MicrophoneInput,createMicrophoneRecognition} from './microphone-asr.mjs';
import {HandsFreeConversation,HANDS_FREE_COPY} from './hands-free.mjs';
import {CloudSpeechPlayer} from './cloud-speech.mjs';
import {ConversationAudioSession} from './audio-session.mjs';
import {locationContext} from './sensor-context.mjs';
import {SoulVisionObserver,captureVisionFrame,VISION_COPY} from './soul-vision.mjs';
import {createSoulChat} from './soul-chat.mjs';
import {SEOUL_PLACES,PlaceFence,outputLanguage,placeFallback} from './seoul-places.mjs';
import {RecordedVoicePlayer,VOICE_PROFILES,voiceFile} from './recorded-voice.mjs';
import {translate,startLanguageUI,getLanguage} from './i18n.mjs';
import {SOULS,SCENARIOS,parseSoulQR,appendPoint,routeDistance,projectRoute,SoulCameraController} from './soul-core.mjs';
let voiceLanguage='en';try{if(['en','ko'].includes(localStorage.getItem('velo-soul-voice-language')))voiceLanguage=localStorage.getItem('velo-soul-voice-language');}catch{}
const $=id=>document.getElementById(id),app=$('app'),audio=$('soulAudio');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let handsFree=null,wakeLock=null,gpsPoint=null,gpsSpeed=null,gpsStatus='';
let activeVoiceSoul='lumi',encounterPhotos=[],companionPending=false,latestPhoto=null;
let selected='lumi',screen='home',camera=null,camState='off',scanTimer=null,timer=null,toastTimer,voiceTimer,voiceSerial=0,ride=null,draft=null,watch=null,gpsEpoch=0,voiceOn=true,currentLine=null;
const journeyStore=new JourneyStore(),journeyPager=new JourneyPager(journeyStore);
const koreanMap=new KoreaMap({getLanguage});
const rideView=new RideView({getLanguage,getPoints:()=>ride?.route?.length?ride.route:gpsPoint&&gpsPoint.accuracy<=60?[gpsPoint]:[],isCameraLive:()=>camState==='live'});
const date=t=>new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric'}).format(t);
const duration=seconds=>`${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`;
const wave='<span class="wave" aria-hidden="true"><span></span><span></span><span></span><span></span></span>';
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function theme(id){selected=id;const s=SOULS[id];document.documentElement.style.setProperty('--accent',s.color);document.documentElement.style.setProperty('--tint',s.tint);document.title=`${s.name} · VELO SOUL`;preloadIntro(id);void bikeMemory.select(id);}
function voiceStatus(t){const targets=screen==='home'?[$('invite-'+activeVoiceSoul)]:document.querySelectorAll('.voice-status');targets.forEach(e=>{if(e)e.textContent=t;});}
const recordedVoice=new RecordedVoicePlayer({audio,onState:state=>{if(state==='playing')liveSpeech.followMedia(audio,audio.currentSrc||audio.src,activeVoiceSoul);else if(['ended','blocked','timeout','error'].includes(state))liveSpeech.stop();paintSoulExpression(document,state==='playing'?'talking':state==='loading'?'thinking':'rest');
 document.body.classList.toggle('voice-playing',state==='playing');
 const messages={loading:'목소리를 준비하고 있어요…',playing:voiceLanguage==='en'?'영어 목소리 재생 중':'한국어 목소리 재생 중',ended:'다시 듣기로 목소리를 들을 수 있어요.',blocked:'소리를 켜려면 듣기 버튼을 눌러주세요.',timeout:'불러오기가 지연돼요. 다시 듣기를 눌러주세요.',error:'소리를 재생하지 못했어요. 다시 듣기를 눌러주세요.'};
 voiceStatus(messages[state]);
}});
const audioSession=new ConversationAudioSession();
const audioDevices=new AudioDevices({session:audioSession});
const liveSpeech=new CloudSpeechPlayer({audioSession,onMouth:frame=>paintSoulMouth(document,frame)});
function preloadIntro(id=selected){const intro=soulIntroduction(id,inputLanguage(),voiceLanguage);if(intro)liveSpeech.preload(intro.text,{soul:id,language:intro.language,source:introductionClip(intro.text,id,intro.language)});}
function stopVoice(){paintSoulExpression(document,"rest");liveSpeech.stop();recordedVoice.stop();voiceSerial++;clearTimeout(voiceTimer);document.body.classList.remove('voice-playing');}
function speak(line,key,id=selected){
 handsFree?.stop();stopVoice();activeVoiceSoul=id;currentLine={line,key,id};
 if(!voiceOn){voiceStatus('목소리를 쉬고 있어요.');return;}
 const src=voiceFile(voiceLanguage,id,key,line);
 if(src&&audioSession.playbackMode!=='media'){liveSpeech.prepare();audioDevices.routeMedia(audio);recordedVoice.play(src);return;}
 liveSpeech.prepare();liveSpeech.speak(line,{language:voiceLanguage,soul:id,source:src,onState:state=>{paintSoulExpression(document,state==='playing'?'talking':state==='loading'?'thinking':'rest');document.body.classList.toggle('voice-playing',state==='playing');voiceStatus(state==='playing'?'한국어 목소리 재생 중':state==='ended'?'다시 듣기로 목소리를 들을 수 있어요.':'목소리를 준비하고 있어요…');}});
}

createAudioDeviceUI({devices:audioDevices,getLanguage,prepare:()=>liveSpeech.prepare(),onModeChange:()=>stopVoice(),onTest:(line,lang,{sample=false}={})=>{voiceOn=true;if(sample)line=soulIntroduction(selected,lang,lang).text;if(soulChat.voiceActive())return soulChat.announceWeather(line,lang);return sayLive(line,lang);}});
const introducedSouls=new Set();
const soulChat=createSoulChat({audioSession,introduced:introducedSouls,getOpening:(id,lang)=>soulIntroduction(id,lang,voiceLanguage),onVoiceIdle:()=>flushCompanionMemories(),onVoiceStart:()=>{if(watch===null)gps();},onClose:()=>{if(!['ride','camera'].includes(screen))stopGPS();},getInputLanguage:inputLanguage,onInputLanguage:setSpokenLanguage,onOpen:()=>{handsFree?.stop();stopVoice();stopPlaceTalk();placeFence?.pause();globalThis.queueMicrotask(paintWeatherUI);},getContext:chatSensorContext,speakReply:sayLive,stopSpeaking:stopVoice,canSpeak:()=>voiceOn,prepareSpeech:()=>{voiceOn=true;preloadIntro();liveSpeech.prepare();}});
let placeFence=null,placeRequest=null,placeEpoch=0,visionObserver=null;
const weather=new WeatherCompanion({getSoul:()=>selected,getLanguage:()=>voiceLanguage,onChange:()=>paintWeatherUI(),
 canSpeak:()=>voiceOn&&!document.hidden&&!placeRequest&&!document.body.classList.contains('voice-playing')&&(soulChat.isOpen()?soulChat.canAnnounceWeather():handsFree?.active&&!handsFree.audioIssue&&['listening','quiet'].includes(handsFree.state)&&Date.now()-handsFree.stateSince>(weather.openingPending()?250:2000)),
 speak:(line,language,notice)=>{const accepted=soulChat.isOpen()?soulChat.announceWeather(line,language):handsFree?.announce(line,language);if(accepted&&screen==='ride'&&ride){(ride.weatherEvents??=[]).push({kind:notice.kind,at:Date.now()});if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent=line;$('quoteTitle').textContent='WEATHER · Open-Meteo';}}return !!accepted;},
 refreshPosition:()=>new Promise(resolve=>{if(!navigator.geolocation||document.hidden||watch===null){resolve(null);return;}navigator.geolocation.getCurrentPosition(pos=>resolve({lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy,time:pos.timestamp}),()=>resolve(null),{enableHighAccuracy:false,maximumAge:30000,timeout:8000});})
});
const bikeMemory=new BikeMemoryUI({getLanguage,getVoice:()=>voiceLanguage,canSpeak:()=>introducedSouls.has(selected)&&voiceOn&&!document.hidden&&!weather.openingPending()&&!placeRequest&&!document.body.classList.contains('voice-playing')&&(soulChat.isOpen()?soulChat.canAnnounceWeather():handsFree?.active&&!handsFree.audioIssue&&['listening','quiet'].includes(handsFree.state)&&Date.now()-handsFree.stateSince>2000),speak:(line,lang)=>soulChat.isOpen()?soulChat.announceWeather(line,lang):handsFree?.announce(line,lang)});
function flushCompanionMemories(){weather.flush();bikeMemory.flush();}
const memoryIdleTimer=setInterval(()=>{if(handsFree?.active||soulChat.voiceActive())flushCompanionMemories();},2500);
document.addEventListener('click',e=>{if(e.target.closest('[data-memory-share]'))void bikeMemory.share();const b=e.target.closest('[data-memory-forget]');if(b)void bikeMemory.forget(b.dataset.memoryForget);});
function paintWeatherUI(){paintWeather(document,weather.snapshot,weather.state,getLanguage(),weather.autoSpeak);const pending=weather.preview();if(pending?.notice.greeting&&voiceOn&&(handsFree?.active||soulChat.voiceActive()))liveSpeech.preload(pending.line,{language:voiceLanguage,soul:selected});}
document.addEventListener('change',e=>{if(e.target.matches('[data-weather-auto]')){weather.autoSpeak=e.target.checked;paintWeatherUI();}});

function stopPlaceTalk(){placeEpoch++;placeRequest?.abort();placeRequest=null;}
function stopCamera(){visionObserver?.stop();visionObserver=null;clearTimeout(scanTimer);scanTimer=null;camera?.stop();camera=null;camState='off';}
function stopGPS(){liveSpeech.cancelPrefetches();weather.stop();gpsPoint=null;gpsSpeed=null;if(ride)ride.latestPoint=null;stopPlaceTalk();placeFence?.pause();gpsEpoch++;if(watch!==null)navigator.geolocation?.clearWatch(watch);watch=null;}
function cleanup(){rideView.destroy();koreanMap.destroy();handsFree?.stop();releaseWakeLock();companionPending=false;document.body.classList.remove('camera-open');$('rideCameraModal')?.remove();soulChat.close();stopPlaceTalk();stopVoice();stopCamera();stopGPS();clearInterval(timer);timer=null;}
function surface(name,html){journeyPager.reset();if(name==='journal'||name==='home'){latestPhoto=null;encounterPhotos=[];}cleanup();currentLine=null;screen=name;app.innerHTML=html;bikeMemory.render();koreanMap.attach([...app.querySelectorAll('[data-korea-map]')].find(el=>!el.closest('.scene-map-layer')),ride?.route||[]);document.querySelectorAll('[data-nav]').forEach(b=>b.setAttribute('aria-current',b.dataset.nav===name?'page':'false'));window.scrollTo(0,0);app.focus({preventScroll:true});}
function updateURL(query){history.replaceState(null,'',query?'/?'+query:'/');}
function shell(copy,body,step=0){return `<section class="experience"><div class="experience-copy"><button class="back" data-nav="home">← 소울 만나기로</button><span class="eyebrow">A LITTLE SOUL. A DIFFERENT RIDE.</span><h1>${copy.title}</h1><p>${copy.text}</p><div class="progress">${['01 만나기','02 함께 달리기','03 기억 남기기'].map((t,i)=>`<span class="${i===step?'active':''}">${t}</span>`).join('')}</div></div><div class="phone">${body}</div></section>`;}
function phoneHead(title,sub,action=''){return `<div class="phone-head"><div><b>${title}</b><small>${sub}</small></div>${action||'<span class="pill"><span class="dot"></span> SOUL CONNECTED</span>'}</div>`;}
function home(){ride=null;draft=null;latestPhoto=null;surface('home',`<div class="wrap home-arrival"><section class="hero"><div><span class="eyebrow">EVERY BICYCLE HOLDS A LITTLE STORY</span><h1>오늘은,<br><em>누구와</em> 달릴까요?</h1><p>자전거에 머무는 작은 영혼들.<br>당신과 나눌 오늘의 한 장면을 기다려요.</p><div class="home-qr-action"><button class="primary" data-action="scan">⌗ &nbsp; 자전거 QR 스캔하기 <span>↗</span></button><p class="small">QR을 비추면 자전거의 소울이 깨어나요.</p></div></div>${mapMarkup(getLanguage())}</section><div class="section-line"><h2>당신을 기다리는 세 친구 <span class="small">/ 03 SOULS</span></h2><span class="small">저마다의 성격, 저마다의 이야기.</span></div><section class="soul-grid" aria-label="세 가지 성격의 소울">${Object.entries(SOULS).map(([id,s])=>`<article class="soul-card" style="--accent:${s.color};--tint:${s.tint}"><div class="card-top"><span class="eyebrow">${s.emoji} ${s.tag}</span><span class="pill">BIKE ${s.number}</span></div><div class="soul-portrait"><img src="${s.image}" alt="${s.name}, ${s.type}" width="240" height="240" decoding="async" loading="${id==='lumi'?'eager':'lazy'}"></div><div class="card-copy"><div class="name-line"><h2>${s.name}</h2><span>${s.en}</span></div><blockquote>“${s.invite}”</blockquote><p>${s.desc}</p><div class="card-actions"><button class="primary" data-meet="${id}">${s.name} 만나기 ↗</button><button class="icon-btn" data-invite="${id}" aria-label="${s.name}의 초대 듣기">♪ <span>듣기</span></button></div><div class="voice-status" id="invite-${id}" aria-live="polite">버튼을 눌러 목소리를 들어보세요.</div></div><div class="qr-mini"><img src="/qr-${id}.svg" alt="${s.name} 전용 QR 코드" width="76" height="76"><div><b>${s.name}에게 바로 연결되는 QR</b><a href="/qr-${id}.png" download="velo-soul-${id}.png">QR 저장하기 ↓</a></div></div></article>`).join('')}</section><div class="home-bottom"><div class="steps"><div class="step"><span>01 / MEET</span><b>QR로 깨우고</b></div><span>↗</span><div class="step"><span>02 / RIDE</span><b>목소리로 함께하고</b></div><span>↗</span><div class="step"><span>03 / REMEMBER</span><b>우리의 기록으로 남아요</b></div></div><p>여정은 끝나도, 작은 이야기는 자전거에 남아요.<br>원한다면 다음 만남을 위해 한마디를 맡겨 주세요.</p></div></div>`);updateURL('');document.title='VELO SOUL · 오늘, 누구와 달릴까요?';}
function welcome(id){theme(id);const s=SOULS[id];surface('welcome',`<section class="meeting-page"><div class="meeting-top"><button class="back" data-nav="home">← 소울 만나기로</button><span class="eyebrow">BIKE ${s.number} / A LITTLE ENCOUNTER</span><a href="/qr-${id}.png" download="velo-soul-${id}.png">QR 저장하기 ↓</a></div><div class="meeting-stage"><div class="meeting-portrait entrance-${id}"><span class="meeting-name" aria-hidden="true">${s.en}</span><span class="meeting-orbit" aria-hidden="true"></span><span class="meeting-spark spark-one" aria-hidden="true">✧</span><span class="meeting-spark spark-two" aria-hidden="true">✦</span><div class="welcome-puppet">${soulPuppet(id)}</div><span class="meeting-trait">${s.type}</span></div><div class="meeting-copy"><span class="eyebrow">A SOUL LIVES HERE</span><h1>안녕, 나는 ${s.name}야.</h1><blockquote>“${s.invite}”</blockquote><p class="meeting-promise">나는 이 자전거에 머물러.<br>오늘의 한 장면은 너와 함께하고 싶어.</p><div class="meeting-actions"><button class="primary accent" data-action="live-companion">함께 출발하기 <span aria-hidden="true">↗</span></button><button class="text-button" data-action="preview">카메라 없이 미리 만나기</button>${audioDeviceButton(getLanguage())}</div><p class="meeting-permission">시작하면 카메라·마이크·위치를 요청해요. 음성과 AI 관찰 장면은 Qwen으로 보내요.</p><details class="meeting-options"><summary>다른 만남 방식과 권한 안내</summary><div class="meeting-options-actions"><button class="secondary" data-invite="${id}">♪ 인사 듣기</button><button class="secondary chat-entry" data-action="chat">소울과 대화하기 ↗</button><button class="secondary" data-action="encounter">카메라와 음성으로 소울 만나기 ↗</button></div><p class="small">위치·카메라·마이크 권한을 요청해요. 말하면 자동으로 Qwen에 보내고 음성으로 답해요. 화면·장소 정보도 함께 사용해요. GPS 허용 후 약 2km 격자 위치로 주변 날씨를 자동 조회해요.</p><p class="small">카메라 입장 시 마이크를 켜고, 음성과 AI 관찰 화면을 Qwen에 보내 대화해요. 녹음 파일은 저장하지 않아요.</p></details><div class="voice-status" aria-live="polite"></div>${bikeMemory.markup('welcome')}</div></div><p class="meeting-footer">잠깐 멈춘 뒤 시작해요. 달리는 동안에는 목소리로 함께해요.</p></section>`);updateURL('bike='+id);}
function cameraMarkup(mode){const scanning=mode==='scan';return `<div class="camera-view ${scanning?'scanning':''}" id="cameraView"><video id="cameraVideo" autoplay playsinline muted aria-label="실시간 후면 카메라"></video><div class="camera-placeholder"><div class="camera-empty"><span class="camera-icon">${scanning?'⌗':'◎'}</span><b>${scanning?'자전거의 QR을 비춰주세요':'당신의 세상으로 초대해요'}</b><p>${scanning?'카메라를 켜고 세 소울의 QR 코드 중 하나를 화면 안에 담아주세요.':'카메라를 켜면 화면 위로 소울이 나타나요.'}</p></div></div><span class="camera-label" id="cameraLabel">CAMERA OFF</span>${scanning?'<div class="scan-target" aria-hidden="true"></div>':`<div class="soul-portal" aria-hidden="true"><i></i><i></i><i></i><span>✦</span><span>✧</span><span>·</span></div><div class="soul-overlay ${selected}" id="soulOverlay">${soulPuppet(selected)}</div>`}<span class="ar-hint">${scanning?'VELO SOUL 전용 QR 인식':'화면 위의 작은 동반자 · 2D AR'}</span></div>${scanning?'':`<details class="camera-settings"><summary>${VOICE_LAYOUT[getLanguage()].settings}</summary>${visionMarkup()}</details>`}`;}
function encounter(preview=false,withVoice=false){encounterPhotos=[];latestPhoto=null;surface('camera',fullCameraMarkup(false));document.body.classList.add('camera-open');updateURL(`bike=${selected}&view=camera`);bindCamera();if(preview)wake();else{if(withVoice){companionPending=true;startHandsFree();if(watch===null)gps();}camera.start();}}
function scanner(){loadQRDecoder();surface('scan',shell({title:'QR 안의 소울을<br>깨워볼까요?',text:'자전거마다 다른 성격, 다른 색의 QR. 휴대폰 기본 카메라로도 바로 소울의 페이지를 열 수 있어요.'},`${phoneHead('자전거 QR 스캔','세 가지 소울 중 한 친구를 만나요','<span class="pill">SCAN & MEET</span>')}${cameraMarkup('scan')}<div class="camera-controls"><button class="primary" id="cameraStart" data-action="camera-start">카메라 켜고 스캔하기</button><button class="text-button" data-nav="home" style="width:100%">목록에서 소울 직접 선택하기</button></div><div class="camera-status" id="cameraStatus" role="status">카메라를 켜면 QR 인식을 시작해요.</div>`));updateURL('view=scan');bindCamera(true);}
function bindCamera(scan=false){camera=new SoulCameraController({video:$('cameraVideo'),onState:(state,message)=>{camState=state;rideView.cameraStatus();const view=$('cameraView');if(!view)return;if(state!=='live')visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=state!=='live';view.classList.toggle('live',state==='live');$('cameraLabel').textContent=state==='live'?'● LIVE CAMERA':view.classList.contains('awakened')?'CAMERA-FREE PREVIEW':'CAMERA OFF';$('cameraStatus').textContent=message;const b=$('cameraStart');if(b){b.disabled=state==='requesting';b.textContent=state==='requesting'?'권한 요청 중…':state==='live'?'카메라 끄기':'카메라 켜기';}if($('wakeButton'))$('wakeButton').textContent='✦';if($('capturePhoto'))$('capturePhoto').disabled=state!=='live';if(scan&&state==='live')scanFrame();else if(state==='live') {wakeCameraEntrance();if(screen==='camera')wake();if(companionPending){companionPending=false;toggleVision();}}}});}
function wakeCameraEntrance(){const view=$('cameraView');if(!view)return;view.classList.remove('awakened');void view.offsetWidth;view.classList.add('awakened');paintSoulExpression(document,'greeting');}
function wake(){if(camState==='requesting'){camera?.stop();camState='off';$('cameraStart').disabled=false;$('cameraStart').textContent='카메라 켜기';}const view=$('cameraView');view.classList.remove('awakened');void view.offsetWidth;view.classList.add('awakened');$('cameraLabel').textContent=camState==='live'?'● LIVE CAMERA':'CAMERA-FREE PREVIEW';$('wakeButton').textContent='✦';if($('rideStart'))$('rideStart').hidden=false;voiceOn=true;if(!handsFree?.active)speak(SOULS[selected].hello,'hello');$('cameraStatus').textContent=camState==='live'?'카메라 화면 위에 소울이 나타났어요.':'카메라 없는 애니메이션 미리보기예요.';}
let qrDecoderLoading=false;
function loadQRDecoder(){if(window.jsQR||qrDecoderLoading)return;qrDecoderLoading=true;const script=document.createElement('script');script.src=`/vendor/jsQR.js?v=${BUILD}`;script.onload=()=>{qrDecoderLoading=false;};script.onerror=()=>{qrDecoderLoading=false;if(screen==='scan')toast('QR 인식을 불러오지 못했어요. 목록에서 소울을 선택해주세요.');};document.head.append(script);}
const scanCanvas=document.createElement('canvas');
function scanFrame(){if(screen!=='scan'||camState!=='live'||!camera)return;const v=$('cameraVideo');if(v?.readyState>=2&&v.videoWidth){const w=Math.min(v.videoWidth,640),h=Math.round(v.videoHeight*w/v.videoWidth);scanCanvas.width=w;scanCanvas.height=h;const ctx=scanCanvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(v,0,0,w,h);const pixels=ctx.getImageData(0,0,w,h);const code=window.jsQR?.(pixels.data,w,h,{inversionAttempts:'dontInvert'});if(code){const id=parseSoulQR(code.data,location.origin);if(id){stopCamera();welcome(id);toast(`${SOULS[id].name}의 QR을 찾았어요!`);return;}$('cameraStatus').textContent='VELO SOUL의 전용 QR 코드를 비춰주세요.';}}scanTimer=setTimeout(scanFrame,180);}
function startRide(){placeFence=new PlaceFence();const s=SOULS[selected];ride={id:crypto.randomUUID(),soul:selected,started:Date.now(),createdAt:Date.now(),route:[],photos:encounterPhotos.splice(0),placeEvents:[],events:[],note:'',seconds:0,gpsStatus:'위치 기록을 켜면 실제 이동 경로가 남아요.',speed:null};if(latestPhoto?.photos===encounterPhotos)latestPhoto.photos=ride.photos;voiceOn=true;renderRide();speak('좋아, 출발하자. 나는 네 곁에 있을게.','start');}
function routeSVG(points){return journeyMap(points); }
function renderRide(){const s=SOULS[selected];surface('ride',`<section class="ride-layout"><div class="ride-primary"><div class="ride-header"><div><span class="eyebrow">02 / TOGETHER ON THE ROAD</span><h1>${s.name}와 함께 달리는 중</h1></div><span class="pill" style="color:var(--accent)">${s.emoji} ${s.tag}</span></div><div class="companion"><img src="${s.image}" alt="곁에 있는 ${s.name}"><span class="orb-text">I'M RIGHT HERE WITH YOU</span></div><div class="quote-box"><div class="quote-top"><span id="quoteTitle">${s.name}의 목소리</span>${wave}</div><p id="rideQuote">“좋아, 출발하자. 나는 네 곁에 있을게.”</p><div class="quote-actions"><span class="voice-status" aria-live="polite"></span><button data-action="replay">다시 듣기 ♪</button></div></div><div class="ride-toolbar">${audioDeviceButton(getLanguage())}<button class="secondary" data-action="hands-free" aria-pressed="false">음성 대화 켜기</button><span class="small" data-live-status role="status"></span><button class="primary accent" data-action="live-companion">GPS · 카메라 · 음성 함께 시작</button><button class="secondary" data-action="ride-camera">◎ 카메라 · 순간 담기</button><button class="secondary chat-entry" data-action="chat">소울과 대화하기 ↗</button><button class="secondary" id="quietButton" data-action="quiet">♪ 목소리 쉬기</button></div></div><aside class="ride-side"><div class="panel"><h2>우리의 지금</h2><div class="metric-row"><div><b id="rideTime">00:00</b><span>함께한 시간</span></div><div><b id="rideDistance">—</b><span>거리 · km</span></div><div><b id="rideSpeed">—</b><span>GPS 속도 · km/h</span></div></div><button class="secondary" id="gpsButton" data-action="gps">위치 기록 켜기</button><p class="sensor-status" id="gpsStatus">${ride.gpsStatus}</p><p id="locationDetail" class="small" data-no-translate></p>${weatherMarkup(getLanguage())}<div id="rideMap">${mapMarkup(getLanguage(),true)}</div><div class="place-panel"><b>근처 장소에서 소울이 말해요</b><p class="small">등록한 서울 장소 3곳 · GPS 허용 후 자동 감지. 대화에는 장소와 날씨 요약을 보내요. 날씨 조회에는 약 2km 격자 위치를 사용해요.</p><p id="placeStatus" class="small" role="status">GPS를 켜면 근처 장소를 기다려요.</p><label class="small" for="placeSelect">위치 없이 상황 테스트</label><select id="placeSelect">${SEOUL_PLACES.map(p=>`<option value="${p.id}">${esc(p.name[getLanguage()])}</option>`).join('')}</select><button class="secondary" data-action="place-demo">선택한 장소 도착 시뮬레이션</button></div></div><div class="panel"><span class="simulation-label">상황 시뮬레이션</span><h2>${s.sense}</h2><p class="small">상황을 골라 ${s.name}의 반응을 들어보세요. ${selected==='lumi'?'카메라의 AI 관찰을 켜면 실제 장면에 반응해요. 아래 버튼은 별도 시뮬레이션이에요.':selected==='mori'?'GPS를 켜면 주변 날씨를 자동으로 확인해요. 아래 버튼은 별도 시뮬레이션이에요.':'가게 정보와 추천은 예시이며 실제 주변 검색이 아니에요.'}</p><div class="scenario-buttons">${SCENARIOS[selected].map(e=>`<button data-scenario="${e.id}" aria-pressed="false">${e.label} ↗</button>`).join('')}</div></div><div class="panel"><h2>소울과 고른 순간 <span id="photoCount" class="small">사진 ${ride.photos.length}장</span></h2><div id="photoStrip" class="${ride.photos.length?'memory-preview':'empty-photos'}">${ride.photos.length?ride.photos.map((src,i)=>photoLink(src,ride.soul,ride.createdAt,i)).join(''):'잠깐 멈춰서, 함께 기억할 장면을 담아요.'}</div><button class="primary" data-action="finish">여정 마치고 기록 남기기 →</button><p class="small" style="margin-bottom:0">주행 중에는 화면 대신 목소리에 귀 기울여요.</p></div></aside></section>`);currentLine={line:'좋아, 출발하자. 나는 네 곁에 있을게.',key:'start'};updateURL(`bike=${selected}&view=ride`);timer=setInterval(updateRideMetrics,1000);updateRideMetrics();}
function updateRideMetrics(){if(!ride||screen!=='ride')return;$('rideTime').textContent=duration((Date.now()-ride.started)/1000);$('rideDistance').textContent=ride.route.length>1?(routeDistance(ride.route)/1000).toFixed(2):'—';$('rideSpeed').textContent=Number.isFinite(ride.speed)?ride.speed.toFixed(1):'—';}
function gps(){
 if(watch!==null){stopGPS();if(ride)ride.speed=null;gpsStatus='위치 기록을 잠시 멈췄어요.';updateGPSUI();return;}
 if(!navigator.geolocation||!window.isSecureContext){gpsStatus='이 환경에서는 위치를 사용할 수 없어요. HTTPS 주소를 휴대폰에서 열어주세요.';updateGPSUI();return;}
 gpsStatus='위치 권한과 GPS 신호를 기다리고 있어요.';weather.start();const epoch=++gpsEpoch;
 watch=navigator.geolocation.watchPosition(pos=>{
  if(epoch!==gpsEpoch||(!['ride','camera'].includes(screen)&&!soulChat.isOpen()))return;
  const c=pos.coords,p={lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,time:pos.timestamp};gpsPoint=p;if(screen==='ride'&&ride)ride.latestPoint=p;
  if(c.accuracy>60){placeFence?.pause();gpsStatus='GPS 오차가 커서 기다리는 중이에요 (±'+Math.round(c.accuracy)+'m).';gpsSpeed=null;if(ride)ride.speed=null;updateGPSUI();return;}
  gpsSpeed=Number.isFinite(c.speed)&&c.speed>=0&&c.speed<25?c.speed*3.6:null;gpsStatus='위치와 주변 날씨를 함께 확인하고 있어요.';weather.position(p);
  if(screen==='ride'&&ride){ride.speed=gpsSpeed;if(ride.route.length<1800&&appendPoint(ride.route,p)&&$('rideMap'))koreanMap.update(ride.route);
   if(!weather.openingPending()&&!soulChat.isOpen()&&!handsFree?.isBusy()&&!placeRequest&&!document.body.classList.contains('voice-playing')){const place=placeFence?.update(p);if(place)triggerPlace(place,'gps');}
   if(!soulChat.isOpen()&&!handsFree?.isBusy()&&!placeRequest&&!document.body.classList.contains('voice-playing')&&selected==='mori'&&ride.speed>22&&!ride.events.includes('actual-speed')){ride.events.push('actual-speed');const line=voiceLanguage==='ko'?SCENARIOS.mori[0].line:'We seem to be riding quite quickly. If you would like, we can ease our pace a little.';if($('rideQuote'))$('rideQuote').textContent=line;sayLive(line,voiceLanguage);}
  }updateGPSUI();
 },err=>{if(epoch!==gpsEpoch)return;gpsStatus=err.code===1?'위치 권한이 꺼져 있어요. 브라우저 사이트 설정에서 허용한 뒤 다시 시도해주세요.':'위치 신호를 찾지 못했어요. 실외에서 다시 시도해주세요.';stopGPS();if(ride)ride.speed=null;updateGPSUI();},{enableHighAccuracy:true,maximumAge:2000,timeout:15000});updateGPSUI();
}
function updateGPSUI(){rideView.update();if(ride)ride.gpsStatus=gpsStatus;if($('gpsStatus'))$('gpsStatus').textContent=gpsStatus;if($('gpsButton'))$('gpsButton').textContent=watch!==null?'위치 기록 멈추기':'위치 기록 켜기';if($('locationDetail'))$('locationDetail').textContent=gpsPoint?gpsPoint.lat.toFixed(5)+', '+gpsPoint.lon.toFixed(5)+' · ±'+Math.round(gpsPoint.accuracy)+' m':'';if($('cameraGPS'))$('cameraGPS').textContent=gpsPoint?'GPS ±'+Math.round(gpsPoint.accuracy)+' m':'GPS ○';updateRideMetrics();paintWeatherUI();}

function setQuote(line,key,title){stopPlaceTalk();currentLine={line,key};$('rideQuote').removeAttribute('data-no-translate');$('rideQuote').textContent='“'+line+'”';$('quoteTitle').textContent=title;speak(line,key);}
function scenario(id){const e=SCENARIOS[selected].find(x=>x.id===id);if(!e)return;if(!ride.events.includes(id))ride.events.push(id);document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scenario===id)));setQuote(e.line,e.audio,'상황 시뮬레이션 · '+e.title);}
function rideCamera(withVoice=false){if($('rideCameraModal'))return;if(!handsFree?.active)stopVoice();stopPlaceTalk();const overlay=document.createElement('div');overlay.id='rideCameraModal';overlay.className='ride-camera-modal camera-fullscreen';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label',translate('함께 기억할 순간'));overlay.innerHTML=fullCameraInner(true);document.body.append(overlay);document.body.classList.add('camera-open');bindCamera();if(withVoice){companionPending=true;startHandsFree();}camera.start();}
function closeRideCamera(){rideView.destroy();companionPending=false;stopCamera();$('rideCameraModal')?.remove();document.body.classList.remove('camera-open');document.querySelector('[data-action="ride-camera"]')?.focus();}
function photoLink(src,soul,time,index){return '<a href="'+esc(src)+'" download="'+photoFilename(soul,time,index+1)+'" title="사진 다시 저장"><img src="'+esc(src)+'" alt="함께 담은 순간 '+(index+1)+'" loading="lazy"></a>';}
function downloadLastPhoto(){const photos=ride?ride.photos:encounterPhotos;const photo=latestPhoto?.photos===photos?latestPhoto:photos.length?{full:photos.at(-1),filename:photoFilename(selected,ride?.createdAt||Date.now(),photos.length)}:null;if(!photo)return;try{downloadPhoto(photo.full,photo.filename);toast('사진 다운로드를 요청했어요. 휴대폰의 다운로드 또는 파일 앱을 확인해주세요.');}catch{toast('사진 다운로드를 시작하지 못했어요. 사진을 다시 눌러주세요.');}}
function capture(){
 if(camState!=='live')return;
 const photos=ride?ride.photos:encounterPhotos;
 let photo;
 try{photo=capturePhoto($('cameraVideo'));}catch{toast('사진을 찍지 못했어요. 카메라가 준비되면 다시 눌러주세요.');return;}
 const capturedAt=Date.now(),filename=photoFilename(selected,capturedAt,photos.length+1);
 photos.push(photo.preview);latestPhoto={full:photo.full,filename,photos};
 // A denied download must not discard the captured journey photo.
 let requested=false;try{downloadPhoto(photo.full,filename);requested=true;}catch{}
 if($('photoCount'))$('photoCount').textContent='사진 '+photos.length+'장';
 if($('photoStrip')){if($('photoStrip').className!=='memory-preview'){$('photoStrip').className='memory-preview';$('photoStrip').textContent='';}$('photoStrip').insertAdjacentHTML('beforeend',photoLink(photo.preview,selected,capturedAt,photos.length-1));}
 if($('cameraThumb')){$('cameraThumb').src=photo.preview;$('cameraThumb').hidden=false;}
 if($('downloadPhoto'))$('downloadPhoto').disabled=false;
 if($('cameraPhotoCount'))$('cameraPhotoCount').textContent='사진 '+photos.length+'장';
 const view=$('cameraView');if(view){view.classList.remove('capture-flash');void view.offsetWidth;view.classList.add('capture-flash');}
 if($('cameraStatus'))$('cameraStatus').textContent='사진 '+photos.length+'장 · 사진을 누르면 다시 저장할 수 있어요.';
 toast(requested?'사진 다운로드를 요청했어요. 휴대폰의 다운로드 또는 파일 앱을 확인해주세요.':'사진 다운로드를 시작하지 못했어요. 사진을 다시 눌러주세요.');
}
function reviewText(r){const s=SOULS[r.soul],events=SCENARIOS[r.soul].filter(e=>r.events?.includes(e.id));return s.diary+(events.length?' 오늘 체험에서는 '+events.map(e=>e.memory).join(' '):'')+(r.photos.length?' 우리가 골라 담은 장면도 여기 남겨 둘게.':'');}
function post(r,actions=false){const s=SOULS[r.soul];return `<article class="post" style="--accent:${s.color};--tint:${s.tint}"><div class="post-head"><img class="avatar" src="${s.image}" alt=""><div><b>${s.name}의 라이딩 일기</b><small>${date(r.createdAt)} · BIKE ${s.number}</small></div><span class="pill">${s.emoji} ${s.tag}</span></div>${routeSVG(r.route)}<div class="post-body"><span class="eyebrow" style="color:var(--accent)">OUR LITTLE JOURNEY / ${duration(r.seconds)}</span><h2>오늘은 네가 내 곁에 있었어.</h2><p>${esc(reviewText(r))}</p>${r.events?.some(e=>e!=='actual-speed')?'<p class="small" style="margin-top:10px">고른 시뮬레이션 상황을 바탕으로 쓴 소울의 후기예요.</p>':''}${r.photos.length?`<div class="post-photos" data-shown="${Math.min(8,r.photos.length)}">${r.photos.slice(0,8).map((src,i)=>photoLink(src,r.soul,r.createdAt,i)).join('')}</div>${r.photos.length>8?`<button class="text-button" data-more-photos="${esc(r.id)}">사진 더 보기</button>`:''}`:'<div class="empty-photos">이번 여정에는 사진을 담지 않았어요.</div>'}<div class="mood-card"><img src="${s.image}" alt="${s.name}의 기분 카드"><div><small>AFTER THE RIDE · 소울의 기분 카드</small><p>${s.mood}</p></div></div>${r.note?`<p class="post-note">${esc(r.note)}</p>`:''}${actions?`<div class="post-actions"><button data-export="${esc(r.id)}">이미지로 저장 ↓</button><button data-delete="${esc(r.id)}">기록 삭제</button></div>`:''}</div></article>`;}
function finish(){if(!ride)return;closeRideCamera();draft={...ride,seconds:Math.floor((Date.now()-ride.started)/1000)};ride=null;surface('finish',`<section class="finish-layout">${post(draft)}<div class="finish-copy">${bikeMemory.markup('farewell')}<span class="eyebrow">03 / A MEMORY TO KEEP</span><h1>길은 끝나도,<br>우리의 이야기는 남아요.</h1><p>${SOULS[selected].name}가 오늘의 여정을 한 장의 일기로 남겼어요. 당신의 한마디도 더해볼까요?</p><label for="rideNote">당신의 한마디 <span class="small">선택 · 160자</span></label><textarea id="rideNote" maxlength="160" rows="4" placeholder="오늘 소울은 어떤 존재로 느껴졌나요?"></textarea><button class="primary accent" id="saveButton" data-action="save">우리의 기록에 남기기 →</button><button class="secondary" data-action="export-draft">카드 이미지로 저장 ↓</button><p class="small" id="saveStatus" style="margin-top:15px">촬영한 사진은 기기에 다운로드하고, 여정의 사진 미리보기와 GPS 경로는 이 브라우저에 보관해요. 다른 사람에게 자동으로 공유되지 않아요.</p><button class="text-button" data-nav="home">기록하지 않고 돌아가기</button><div class="voice-status"></div></div></section>`);updateURL(`bike=${selected}&view=memory`);playLiveVoice(MEMORY_COPY[voiceLanguage].farewell,voiceLanguage);}
const storage=(mode,action)=>journeyStore.run(mode,action);
async function migrateLegacy(){try{if(localStorage.getItem('velo-final-migrated'))return;const old=JSON.parse(localStorage.getItem('velo-soul-journeys-v2')||'[]');if(Array.isArray(old))for(const r of old){if(!r||!Object.hasOwn(SOULS,r.soul)||typeof r.id!=='string')continue;await storage('readwrite',s=>s.put({id:r.id,soul:r.soul,createdAt:Number(r.createdAt)||Date.now(),seconds:Number(r.seconds)||0,route:[],photos:[],placeEvents:[],events:[],note:typeof r.note==='string'?r.note.slice(0,160):''}));}localStorage.setItem('velo-final-migrated','1');}catch{}}
async function loadRecordCount(){try{await migrateLegacy();const count=await storage('readonly',s=>s.count());document.querySelectorAll('.record-count').forEach(e=>e.textContent=count);}catch{}}
async function save(){if(!draft)return;$('saveButton').disabled=true;draft.note=$('rideNote').value.slice(0,160);try{await storage('readwrite',s=>s.put(draft));draft=null;await journal();toast('우리의 기록에 남겼어요.');}catch{$('saveButton').disabled=false;$('saveStatus').textContent='이 브라우저에 저장하지 못했어요. 카드 이미지로 먼저 보관해주세요.';}}
async function loadJournalPage(){
 if(screen!=='journal'||journeyPager.busy||!journeyPager.hasMore)return;
 const serial=journeyPager.generation;
 const button=$('journalMore');button.disabled=true;
 $('journalStatus').hidden=false;$('journalStatus').textContent='기억을 불러오는 중…';
 try{
  const page=await journeyPager.next();if(!page||screen!=='journal'||serial!==journeyPager.generation)return;
  document.querySelectorAll('.record-count').forEach(e=>e.textContent=page.total);
  if(journeyPager.records.length){$('journalGrid').insertAdjacentHTML('beforeend',page.records.map(r=>post(r,true)).join(''));}
  else{$('journalGrid').className='';$('journalGrid').innerHTML='<div class="empty"><span style="font-size:35px">✳</span><h2>첫 번째 이야기를 기다려요.</h2><p>소울과 함께 달리고, 우리의 순간을 남겨보세요.</p><button class="primary" data-nav="home">소울 만나러 가기 ↗</button></div>';}
  $('journalStatus').hidden=true;button.hidden=!page.hasMore;button.textContent='기록 더 보기';
 }catch{if(screen==='journal'&&serial===journeyPager.generation){$('journalStatus').textContent='기록을 불러오지 못했어요. 다시 시도해주세요.';button.hidden=false;button.textContent='다시 시도';}}
 finally{if(screen==='journal'&&serial===journeyPager.generation)button.disabled=false;}
}
async function journal(){document.title='우리의 기록 · VELO SOUL';surface('journal','<div class="journal"><span class="eyebrow">OUR LITTLE JOURNEYS</span><h1>우리가 함께한 순간.</h1><p class="small">소울의 시선으로 남긴 작은 라이딩 일기. 이 기기에서만 볼 수 있어요.</p><div id="journalList"><div class="journal-grid" id="journalGrid"></div><p class="small" id="journalStatus" style="margin:24px 0" role="status">기억을 불러오는 중…</p><button class="secondary" style="margin-top:24px" id="journalMore" data-action="journal-more" hidden>기록 더 보기</button></div></div>');updateURL('view=journeys');const serial=journeyPager.generation;await migrateLegacy();if(screen==='journal'&&serial===journeyPager.generation)await loadJournalPage();}
function showMorePhotos(button){const record=draft?.id===button.dataset.morePhotos?draft:journeyPager.records.find(r=>r.id===button.dataset.morePhotos);const grid=button.previousElementSibling;if(!record||!grid?.matches('.post-photos'))return;const start=Number(grid.dataset.shown)||0,end=Math.min(start+8,record.photos.length);grid.insertAdjacentHTML('beforeend',record.photos.slice(start,end).map((src,i)=>photoLink(src,record.soul,record.createdAt,start+i)).join(''));grid.dataset.shown=end;button.hidden=end>=record.photos.length;}
async function exportCard(r){toast('여정 카드를 만들고 있어요.');try{const s=SOULS[r.soul],c=document.createElement('canvas');c.width=900;c.height=r.photos.length?1720:1450;const x=c.getContext('2d');const drawText=(text,a,b)=>x.fillText(translate(text),a,b);x.fillStyle='#f7f8f2';x.fillRect(0,0,c.width,c.height);x.fillStyle=s.color;x.font='600 20px sans-serif';drawText('VELO SOUL / OUR LITTLE JOURNEY',55,62);x.fillStyle='#252e29';x.font='bold 43px sans-serif';drawText(s.name+'의 라이딩 일기',55,133);x.font='20px sans-serif';x.fillStyle='#748174';drawText(date(r.createdAt)+' · 함께한 시간 '+duration(r.seconds),55,174);x.fillStyle=s.tint;x.fillRect(55,215,790,310);const points=projectRoute(r.route,790,310);if(points.length>1){x.beginPath();points.forEach(([a,b],i)=>i?x.lineTo(a+55,b+215):x.moveTo(a+55,b+215));x.strokeStyle=s.color;x.lineWidth=7;x.lineJoin='round';x.stroke();}else{x.fillStyle='#748174';x.font='23px sans-serif';drawText('위치 기록 없이 함께한 여정',270,375);}x.font='17px sans-serif';x.fillStyle='#748174';drawText('GPS TRACE · '+(points.length>1?'실제 기록 / 도로 지도 아님':'기록된 경로 없음'),75,500);let y=580;function wrap(t,size=25,localize=true){t=localize?translate(t):t;x.font=size+'px sans-serif';let line='';for(const ch of t){if(ch==='\n'||x.measureText(line+ch).width>780){x.fillText(line,55,y);y+=37;line=ch==='\n'?'':ch;}else line+=ch;}if(line){x.fillText(line,55,y);y+=37;}}x.fillStyle='#252e29';wrap(reviewText(r));if(r.events?.some(e=>e!=='actual-speed')){x.fillStyle='#748174';wrap('시뮬레이션 상황을 포함한 체험 후기',17);}y+=20;if(r.photos.length){let i=0;for(const src of r.photos.slice(0,4)){const img=new Image();img.src=src;await img.decode();const size=184,bx=55+i*202;const crop=Math.min(img.width,img.height);x.drawImage(img,(img.width-crop)/2,(img.height-crop)/2,crop,crop,bx,y,size,size);i++;}y+=220;}const img=new Image();img.src=s.image;await img.decode();x.globalCompositeOperation='multiply';x.drawImage(img,45,y,150,150);x.globalCompositeOperation='source-over';x.fillStyle=s.color;x.font='24px sans-serif';drawText(s.mood,215,y+80);y+=178;if(r.note){x.fillStyle='#252e29';wrap(r.note,21,false);}x.fillStyle='#748174';x.font='17px sans-serif';drawText('A LITTLE SOUL. A DIFFERENT RIDE.',55,c.height-40);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw new Error();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`velo-soul-${r.soul}-${r.createdAt}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('여정 카드 이미지를 저장했어요.');}catch{toast('이미지를 만들지 못했어요. 다시 시도해주세요.');}}
function navigate(target){if((ride||draft)&&!confirm(translate('아직 저장하지 않은 여정이 있어요. 기록하지 않고 나갈까요?')))return;ride=null;draft=null;target==='journal'?journal():home();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.sceneMode){rideView.switch(b.closest('.camera-fullscreen'),b.dataset.sceneMode);return;}if(b.hasAttribute('data-scene-center')){rideView.center();return;}if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav);return;}if(b.dataset.meet){e.preventDefault();welcome(b.dataset.meet);voiceOn=true;speak(SOULS[b.dataset.meet].hello,'hello',b.dataset.meet);return;}if(b.dataset.invite){voiceOn=true;speak(SOULS[b.dataset.invite].hello,'hello',b.dataset.invite);return;}if(b.dataset.scenario){scenario(b.dataset.scenario);return;}if(b.dataset.morePhotos){showMorePhotos(b);return;}if(b.dataset.export){const r=journeyPager.records.find(r=>r.id===b.dataset.export);if(r)exportCard(r);return;}if(b.dataset.delete){if(confirm(translate('이 기기에 저장한 여정과 사진을 삭제할까요?'))){try{await storage('readwrite',s=>s.delete(b.dataset.delete));await journal();toast('기록을 삭제했어요.');}catch{toast('기록을 삭제하지 못했어요.');}}return;}switch(b.dataset.action){case 'live-companion':startLiveCompanion();break;case 'camera-exit':companionPending=false;if(screen==='ride')closeRideCamera();else welcome(selected);break;case 'hands-free':toggleHandsFree();break;case 'audio-unlock':liveSpeech.prepare();voiceOn=true;if(currentLine?.dynamicLanguage)sayLive(currentLine.line,currentLine.dynamicLanguage);break;case 'voice-test':liveSpeech.prepare();voiceOn=true;sayLive(getLanguage()==='ko'?'나 여기 있어. 풍경과 장소 이야기를 목소리로 들려줄게.':'I’m here with you. I’ll share what we notice along the way.',outputLanguage(getLanguage()));break;case 'vision-toggle':toggleVision();break;case 'vision-replay':if(currentLine?.dynamicLanguage){voiceOn=true;sayLive(currentLine.line,currentLine.dynamicLanguage);}break;case 'chat':soulChat.open(selected);break;case 'place-demo':triggerPlace(SEOUL_PLACES.find(p=>p.id===$('placeSelect').value),'simulation');break;case 'about':$('infoDialog').showModal();break;case 'scan':scanner();break;case 'encounter':encounter(false,true);break;case 'preview':encounter(true);break;case 'camera-start':if(camState==='live'){companionPending=false;visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=true;camera?.stop();camState='off';rideView.cameraStatus();clearTimeout(scanTimer);$('cameraView').classList.remove('live');$('cameraLabel').textContent=$('cameraView').classList.contains('awakened')?'CAMERA-FREE PREVIEW':'CAMERA OFF';$('cameraStatus').textContent='카메라를 껐어요.';b.textContent='카메라 켜기';if($('capturePhoto'))$('capturePhoto').disabled=true;}else await camera?.start();break;case 'wake':wake();break;case 'ride-start':startRide();break;case 'replay':handsFree?.stop();if(currentLine){voiceOn=true;if($('quietButton'))$('quietButton').textContent='♪ 목소리 쉬기';currentLine.dynamicLanguage?sayLive(currentLine.line,currentLine.dynamicLanguage):speak(currentLine.line,currentLine.key,currentLine.id||selected);}break;case 'quiet':handsFree?.stop();voiceOn=!voiceOn;b.textContent=voiceOn?'♪ 목소리 쉬기':'♪ 목소리 켜기';if(!voiceOn){stopVoice();voiceStatus('조용히 곁에 있을게.');}else if(currentLine)currentLine.dynamicLanguage?sayLive(currentLine.line,currentLine.dynamicLanguage):speak(currentLine.line,currentLine.key);break;case 'gps':gps();break;case 'ride-camera':rideCamera(true);break;case 'close-camera':closeRideCamera();break;case 'journal-more':loadJournalPage();break;case 'capture':capture();break;case 'download-photo':downloadLastPhoto();break;case 'finish':finish();break;case 'save':save();break;case 'export-draft':draft.note=$('rideNote').value.slice(0,160);exportCard(draft);break;}});
$('infoDialog').querySelector('.dialog-close').onclick=()=>$('infoDialog').close();
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('rideCameraModal')&&!soulChat.isOpen()&&!document.querySelector('.audio-device-dialog[open]'))closeRideCamera();if(e.key==='Tab'&&$('rideCameraModal')&&!soulChat.isOpen()&&!document.querySelector('.audio-device-dialog[open]')){const items=[...$('rideCameraModal').querySelectorAll('button:not(:disabled),select:not(:disabled)')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)return;handsFree?.stop();releaseWakeLock();companionPending=false;visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=true;stopPlaceTalk();stopVoice();if(camera){camera.stop();camState='off';clearTimeout(scanTimer);$('cameraView')?.classList.remove('live');if($('cameraLabel'))$('cameraLabel').textContent='CAMERA PAUSED';if($('cameraStatus'))$('cameraStatus').textContent='화면을 떠나 카메라를 껐어요. 다시 켜려면 버튼을 눌러주세요.';if($('cameraStart')){$('cameraStart').disabled=false;$('cameraStart').textContent='카메라 다시 켜기';}if($('capturePhoto'))$('capturePhoto').disabled=true;}if(watch!==null){stopGPS();if(ride)ride.speed=null;gpsStatus='화면을 떠나 위치 기록을 멈췄어요. 다시 켜서 이어갈 수 있어요.';updateGPSUI();}});
window.addEventListener('pagehide',()=>{clearInterval(memoryIdleTimer);bikeMemory.controller?.abort();cleanup();audioSession.dispose();});window.addEventListener('popstate',()=>{ride=null;draft=null;routeFromURL();});
function routeFromURL(){const p=new URLSearchParams(location.search),id=p.get('bike');if(p.get('view')==='journeys')journal();else if(p.get('view')==='scan')scanner();else if(Object.hasOwn(SOULS,id)){theme(id);p.get('view')==='camera'?encounter():welcome(id);}else home();}
startLanguageUI();$('voiceSelect').value=voiceLanguage;$('voiceSelect').addEventListener('change',e=>{const active=handsFree?.active;liveSpeech.prepare();setSpokenLanguage(e.target.value);soulChat.setInputLanguage(e.target.value);if(active){handsFree.start(selected,inputLanguage());requestWakeLock();}else if(!soulChat.isOpen()&&['welcome','camera'].includes(screen)){voiceOn=true;speak(SOULS[selected].hello,'hello');}});
$('languageSelect').addEventListener('change',()=>{bikeMemory.render();koreanMap.language();rideView.language();document.querySelectorAll('[data-weather-card]').forEach(e=>e.outerHTML=weatherMarkup(getLanguage()));paintWeatherUI();handsFree?.stop();visionObserver?.stop();const panel=$('visionPanel');if(panel)panel.outerHTML=visionMarkup();if($('visionToggle'))$('visionToggle').disabled=camState!=='live';if($('placeSelect'))for(const option of $('placeSelect').options)option.textContent=SEOUL_PLACES.find(p=>p.id===option.value).name[getLanguage()];});
const microphoneInput=new MicrophoneInput({audioSession,onLevel:level=>{document.querySelectorAll('[data-mic-level]').forEach(m=>{m.value=level;m.setAttribute('aria-valuetext',Math.round(level*100)+'%');});}});
const CloudRecognition=createMicrophoneRecognition({input:microphoneInput,Socket:globalThis.WebSocket});
handsFree=new HandsFreeConversation({introduced:introducedSouls,getOpening:(id,lang)=>soulIntroduction(id,lang,voiceLanguage),onOpening:text=>{if($('cameraCaption'))$('cameraCaption').textContent=text;},Recognition:CloudRecognition,releaseInput:()=>microphoneInput.release(),getContext:chatSensorContext,speak:playLiveVoice,stopSpeech:stopVoice,onState:paintHandsFree,onTranscript:(text,final=true)=>{for(const id of ['cameraCaption','heardText']){const el=$(id);if(el){el.textContent=text;el.dataset.transcriptState=final?'confirmed':'interim';}}},onReply:text=>{if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent=text;$('quoteTitle').textContent='VOICE · Qwen';}}});
document.addEventListener('change',e=>{if(e.target.id==='liveInputLanguage'){const lang=e.target.value;setSpokenLanguage(lang);if(handsFree.active){handsFree.start(selected,lang);requestWakeLock();}}});
routeFromURL();if(screen!=='journal')setTimeout(loadRecordCount,0);

function playLiveVoice(line,lang,id=selected,onState=()=>{}){stopVoice();activeVoiceSoul=id;currentLine={line,key:null,id,dynamicLanguage:lang};if($('cameraCaption'))$('cameraCaption').textContent=line;if(!voiceOn){onState('unavailable');return;}liveSpeech.speak(line,{language:lang,soul:id,source:introductionClip(line,id,lang),onState:state=>{paintSoulExpression(document,state==='playing'?'talking':state==='loading'?'thinking':'listening');document.body.classList.toggle('voice-playing',state==='playing'||state==='loading');voiceStatus(({loading:'목소리를 준비하고 있어요…',playing:lang==='ko'?'한국어 목소리 재생 중':'영어 목소리 재생 중',ended:'다시 듣기로 목소리를 들을 수 있어요.',blocked:'소리를 켜려면 듣기 버튼을 눌러주세요.',unavailable:'소리를 재생하지 못했어요. 다시 듣기를 눌러주세요.'})[state]);onState(state);}});}
async function triggerPlace(place,source){if(!ride||!place||screen!=='ride'||soulChat.isOpen())return;stopPlaceTalk();const epoch=placeEpoch,rideId=ride.id,lang=voiceLanguage;placeRequest=new AbortController();const controller=placeRequest;const timeout=setTimeout(()=>controller.abort(),30000);const status=$('placeStatus');status.textContent=(source==='simulation'?'SIMULATION · ':'GPS · ')+place.name[getLanguage()];let line=placeFallback(place,selected,lang),generated=false;try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({soul:selected,language:lang,event:{placeId:place.id,source},messages:[{role:'user',content:source==='simulation'?'Imagine passing this catalog place. Say one short in-character line.':'My device reports entering this catalog place area. Say one short in-character line.'}]})});if(response.ok){const data=await response.json();if(typeof data.reply==='string'&&data.reply.trim()&&data.soul===selected){line=data.reply;generated=true;}}}catch{}finally{clearTimeout(timeout);if(epoch===placeEpoch)placeRequest=null;}if(epoch!==placeEpoch||!ride||ride.id!==rideId||screen!=='ride')return;if(source==='simulation'&&!generated)line=(lang==='ko'?'가상의 장소 도착 체험이야. ':'This is a simulated arrival. ')+line;ride.placeEvents.push({placeId:place.id,source,generated,at:Date.now()});$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent='“'+line+'”';$('quoteTitle').textContent=(source==='simulation'?'SIMULATION':'GPS')+' · '+place.name[getLanguage()];status.textContent=(source==='simulation'?'SIMULATION · ':'GPS · ')+(generated?'Qwen · ':translate('기본 안내 / AI 사용 불가')+' · ')+place.name[getLanguage()];sayLive(line,lang);}

function visionMarkup(){const c=VISION_COPY[getLanguage()];return `<section class="vision-panel" id="visionPanel" data-no-translate><p class="vision-notice">${c.notice}</p><button class="secondary" id="visionToggle" data-action="vision-toggle" aria-pressed="false" disabled>${c.start}</button><p id="visionStatus" class="small" role="status">${c.off}</p><p id="visionReply" class="vision-reply" aria-live="polite" hidden></p><button class="text-button" id="visionReplay" data-action="vision-replay" hidden>${c.listen}</button></section>`;}
function toggleVision(){if(visionObserver?.active){visionObserver.stop();if(!handsFree?.active)stopVoice();return;}if(camState!=='live'){toast(VISION_COPY[getLanguage()].camera);return;}stopPlaceTalk();if(!handsFree?.active)stopVoice();visionObserver?.stop();visionObserver=new SoulVisionObserver({capture:()=>captureVisionFrame($('cameraVideo')),getContext:()=>chatSensorContext(false).context,canObserve:()=>!weather.openingPending()&&!document.hidden&&camState==='live'&&!soulChat.isOpen()&&!placeRequest&&!handsFree?.isBusy()&&!document.body.classList.contains('voice-playing'),onState:state=>{const c=VISION_COPY[getLanguage()];if($('visionToggle')){$('visionToggle').textContent=visionObserver?.active?c.stop:c.start;$('visionToggle').setAttribute('aria-pressed',String(!!visionObserver?.active));}if($('visionStatus'))$('visionStatus').textContent=c[state]||c.failed;},onReply:(result,lang)=>{if($('visionReply')){$('visionReply').hidden=false;$('visionReply').textContent=result.reply;$('visionReplay').hidden=false;}if(ride){(ride.visionEvents??=[]).push({scene:result.scene,reply:result.reply,at:Date.now()});if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent='“'+result.reply+'”';$('quoteTitle').textContent='CAMERA · Qwen';}}sayLive(result.reply,lang);}});visionObserver.start(selected,voiceLanguage);}

function chatSensorContext(withImage=true){const context={};const location=watch!==null?locationContext(gpsPoint,gpsSpeed):null;if(location)context.location=location;const weatherId=weather.reference();if(weatherId)context.weatherId=weatherId;const cameraConnected=camState==='live'&&!!visionObserver?.active;const result={context,cameraConnected};if(withImage&&cameraConnected){try{result.image=captureVisionFrame($('cameraVideo'));}catch{}}return result;}
function fullCameraMarkup(riding){return `<section class="camera-fullscreen">${fullCameraInner(riding)}</section>`;}
function fullCameraInner(riding){return `${cameraMarkup('encounter')}${rideViewMarkup(getLanguage())}<div class="camera-top"><button class="camera-round" data-action="camera-exit" aria-label="닫기">×</button><div class="camera-name"><b>${SOULS[selected].en}</b><span id="cameraGPS">GPS ${watch!==null?'●':'○'}</span></div><button class="camera-round" data-action="voice-test" aria-label="목소리 듣기">♪</button></div><div class="camera-weather">${weatherMarkup(getLanguage())}</div>${handsFreeMarkup()}<span class="camera-focus" aria-hidden="true"><i></i></span><div class="camera-live-caption"><p id="cameraCaption" data-no-translate></p><span class="voice-status" aria-live="polite"></span></div><div class="camera-bottom"><div class="camera-mode-row"><button id="cameraStart" data-action="camera-start">카메라 켜기</button><button data-action="chat">소울과 대화하기 ↗</button><button data-action="gps">GPS</button></div><div class="camera-shutter-row"><button class="camera-photo-preview" id="downloadPhoto" data-action="download-photo" aria-label="사진 다시 저장" ${(riding?ride.photos:encounterPhotos).length?'':'disabled'}><img id="cameraThumb" alt="최근 촬영 사진" ${(riding?ride.photos:encounterPhotos).length?'src="'+esc((riding?ride.photos:encounterPhotos).at(-1))+'"':'hidden'}><span id="cameraPhotoCount">사진 ${riding?ride.photos.length:encounterPhotos.length}장</span><small>저장 ↓</small></button><button class="camera-shutter" id="capturePhoto" data-action="capture" aria-label="순간 담기" disabled><span></span></button><button class="camera-round" id="wakeButton" data-action="wake" aria-label="등장 애니메이션 다시 보기">✦</button></div><div class="camera-status" id="cameraStatus" role="status">카메라 권한을 기다리고 있어요.</div>${riding?'<button class="camera-continue" data-action="finish" data-no-translate>'+({ko:'오늘은 여기까지 · 작별하기',en:'Pause here · say goodbye',zh:'今天就到这里 · 告别'})[getLanguage()]+'</button>':'<button id="rideStart" class="camera-continue" data-action="live-companion" hidden>GPS · 카메라 · 음성 함께 시작 →</button>'}</div>`;}
async function startLiveCompanion(){if(companionPending)return;if(!ride)startRide();voiceOn=true;liveSpeech.prepare();if(watch===null)gps();companionPending=true;if(!$('rideCameraModal'))rideCamera();else if(camState==='live'){companionPending=false;if(!visionObserver?.active)toggleVision();}else camera?.start();if(!handsFree?.active)toggleHandsFree();}

function sayLive(line,lang,id=selected,onState=()=>{}){if(handsFree?.active)return handsFree.announce(line,lang,onState);return playLiveVoice(line,lang,id,onState);}
async function requestWakeLock(){try{if(!document.hidden&&navigator.wakeLock&&!wakeLock){const lock=await navigator.wakeLock.request('screen');if(document.hidden||!handsFree?.active){await lock.release();return;}wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null;});}}catch{}}
function releaseWakeLock(){wakeLock?.release().catch(()=>{});wakeLock=null;}
function paintHandsFree(state){paintSoulExpression(document,['thinking','transcribing','synthesizing'].includes(state)?'thinking':state==='speaking'?'talking':['listening','hearing','quiet'].includes(state)?'listening':'rest');if(state==='listening')setTimeout(()=>flushCompanionMemories(),350);const c=HANDS_FREE_COPY[getLanguage()];document.querySelectorAll('[data-action="hands-free"]').forEach(b=>{b.textContent=handsFree?.active?c.stop:c.start;b.setAttribute('aria-pressed',String(!!handsFree?.active));});document.querySelectorAll('[data-live-status]').forEach(e=>e.textContent=c[state]||c.failed);document.querySelectorAll('.camera-conversation').forEach(e=>e.dataset.voiceState=state);document.querySelectorAll('[data-action="audio-unlock"]').forEach(e=>e.hidden=!handsFree?.audioIssue);if(!handsFree?.active)releaseWakeLock();}
function inputLanguage(){try{const saved=localStorage.getItem('velo-soul-input-language');if(['en','ko','zh','auto'].includes(saved))return saved;}catch{}return voiceLanguage;}
function setSpokenLanguage(lang){voiceLanguage=lang==='ko'?'ko':'en';try{localStorage.setItem('velo-soul-input-language',lang);localStorage.setItem('velo-soul-voice-language',voiceLanguage);}catch{}$('voiceSelect').value=voiceLanguage;const select=$('liveInputLanguage');if(select)select.value=lang;preloadIntro();if(visionObserver?.active)visionObserver.start(selected,voiceLanguage);}
function startHandsFree(){if(handsFree?.active)return;stopPlaceTalk();stopVoice();voiceOn=true;preloadIntro();liveSpeech.prepare();const lang=$('liveInputLanguage')?.value||inputLanguage();handsFree.start(selected,lang);requestWakeLock();}
function toggleHandsFree(){if(handsFree?.active){handsFree.stop();return;}startHandsFree();}
function handsFreeMarkup(){const c=HANDS_FREE_COPY[getLanguage()],u=VOICE_LAYOUT[getLanguage()];return `<section class="camera-conversation" data-no-translate data-voice-state="${handsFree?.state||'off'}"><div class="conversation-heading"><span class="connection-orb" aria-hidden="true"></span><div><span class="conversation-kicker">${SOULS[selected].en} · ${u.live}</span><p data-live-status role="status">${c[handsFree?.state||'off']||c.off}</p></div><div class="voice-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></div><p id="heardText" class="heard-text" aria-live="polite"></p><div class="conversation-controls"><button class="conversation-toggle" data-action="hands-free" aria-pressed="${!!handsFree?.active}">${handsFree?.active?c.stop:c.start}</button><div class="mic-level-row"><span>${c.mic}</span><meter data-mic-level min="0" max="1" value="0" aria-label="${c.mic}"></meter></div><button class="audio-retry" data-action="audio-unlock" hidden>${u.sound}</button></div><p class="conversation-flow">${u.flow}</p>${audioDeviceButton(getLanguage())}<details class="hands-free-help"><summary>${u.settings}</summary><p>${c.languageHint}</p><select id="liveInputLanguage" aria-label="Preferred language">${[['auto','Auto · 자동 · 自动'],['en','English'],['ko','한국어'],['zh','中文 → English']].map(([value,label])=>`<option value="${value}" ${value===(handsFree?.language||inputLanguage())?'selected':''}>${label}</option>`).join('')}</select><p>${c.notice}</p></details></section>`;}


// The loader only declares success after the initial route has mounted.
window.dispatchEvent(new window.Event('velo:ready'));
